from pathlib import Path
import csv,json,hashlib,datetime
root=Path('/workspace/scratch/70444ed5f561/auto2000_run');out=root/'reports';plan=Path('/workspace/scratch/70444ed5f561/plan_expansion/instruments/initial_hypotheses.csv')
original=list(csv.DictReader(plan.open(encoding='utf8')))
A={}
def put(i,status,scope,refs,finding,counter,missing):
 A[i]=dict(assessment_status=status,status_scope=scope,evidence_refs=refs,assessment=finding,strongest_countercase=counter,remaining_identification_gap=missing,initial_business_mechanism_status='unresolved',causal_effect_established=False)
put('H01','unresolved','The dominant cause of low monthly use was not identified.',['market:M011','market:M012','reviews:REV-0005','reviews:REV-0003','validation:V001'],'Episodic jobs and useful booking accounts exist; a current multi-vehicle limitation is also reported.','Preventable friction remains a credible rival; low-use owner anecdotes are not a Digiroom cohort.','Need job-due activity, repeated task attempts, nonusers and completed outcomes.')
put('H02','partly_corroborated','Complementary app/human use is reported; context preservation and relative superiority remain unresolved.',['narratives:N007','narratives:N071','reviews:REV-0002','market:M041'],'One BYD owner reports app booking with WhatsApp reminders; a historical Auto2000 project reports assisted-channel preference.','The example may be complementary reminders rather than exception handling; current unresolved chat is also reported.','Need equivalent tasks, exceptions, preserved context, adviser effort and outcomes by chosen channel.')
put('H03','unresolved','Actual Digiroom-to-branch lead actionability was not observed.',['reviews:REV-0030','reviews:REV-0035','reviews:REV-0022','journeys:UX05','competition:COMP-038'],'Published/request states and alleged mToyota booking episodes justify separating request from confirmation.','Positive mToyota accounts and an unsubmitted Auto2000 preview cannot establish an Auto2000 routing failure.','Need source-linked lead IDs, assignment/contact timestamps, qualification and delivery records.')
put('H04','partly_corroborated','Advertised job overlap is supported; harmful fragmentation or an integration opportunity larger than expansion is unresolved.',['competition:COMP-001','competition:COMP-002','competition:COMP-007','journeys:UX12'],'OEM, dealer and partner routes advertise overlapping purchase and ownership jobs.','Clear complementary roles may already work; cross-app data entry and customer confusion were not tested.','Need complete matched cross-property tasks, repeated inputs and customer outcomes.')
put('H05','unresolved','Existing comparison and finance functions were observed; effects of situation-specific cost support were not measured.',['journeys:UX02','journeys:UX03','journeys:UX04','market:M003','market:M024','narratives:N035'],'The comparison completed and the simulator exposed a repeatable insurance/cash-flow trade-off without personal contact data.','Affordability and model fit may bind despite good information; an airbag representation error does not make the entire comparison unusable.','Need buyer comprehension/choice evidence separating information, affordability and available offers.')
put('H06','unresolved','No lost-before-inquiry population or like-for-like lost-shortlist outcome was observed.',['market:M002','market:M024','narratives:N018','narratives:N035','validation:V015'],'Narratives and choice research make budget, service access and offer fit plausible constraints.','A relevant offer may exist but be poorly found; publicly observed prices need exact variant/location matching.','Need rejection reasons, actual available inventory, credit, shortlists and deliveries.')
put('H07','partly_corroborated','HEV engine maintenance and eligible scheduled-service programs are supported; protected commercial capture is unmeasured.',['market:M011','market:M016','competition:COMP-003','competition:COMP-004'],'HEV contact opportunities cannot be inferred from BEV maintenance economics alone.','Owners can defer or move service despite technical need or program eligibility.','Need installed-base cohorts, mileage, entitlement, jobs due, dealer capture and realized contribution.')
put('H08','partly_corroborated','BEV reduction in some routine work is supported; profitable infrequent unmet jobs remain unresolved.',['market:M012','market:M013','competition:COMP-005','competition:COMP-030','reviews:REV-0042'],'Technical and published capability evidence identifies distinct diagnostic, battery and emergency jobs.','Needs may already be served, infrequent, OEM-controlled or unprofitable for Auto2000.','Need unmet-job incidence, willingness to use/pay, actual capability and contribution.')
put('H09','unresolved','A current widespread Digiroom history problem or its relative importance was not established.',['narratives:N066','narratives:N067','reviews:REV-0014','competition:COMP-001','validation:V016'],'Historical usability findings and record-value narratives separate feature existence from scope and completeness.','Older app builds, account linkage or normal completion lag may explain accounts; positive history experiences exist.','Need current version/account tests, repair-order timing and record lineage.')
put('H10','partly_corroborated','Historical app/receipt differences and legitimate estimate transitions are documented; current avoidable uncertainty remains unresolved.',['narratives:N066','market:M046','competition:COMP-013','journeys:UX03','journeys:UX04'],'One historical study reports a branch-discount/app mismatch; current operator terms explicitly make estimates conditional.','Inspection, authorized scope or disclosed financing choices can legitimately change amounts.','Need linked estimate, authorization, discount, invoice and customer interpretation for current jobs.')
put('H11','unresolved','A local capability route was observed, without wrong-routing or reduced-travel outcomes.',['journeys:UX08','competition:COMP-018','competition:COMP-030','competition:COMP-031'],'B&P branch search returned a specialist branch; competitor terms show service geographies differ by task.','An initial no-branch state was resolved by another locality; it is not universal failure.','Need actual wrong-branch contacts, reassignments, capability and travel outcomes.')
put('H12','unresolved','EV skill/bay utilization and displaced contribution were unavailable.',['competition:COMP-030','competition:COMP-031','validation:V011','journeys:UX08'],'Advertised emergency coverage and staff accounts indicate operational conditions worth examining.','Published capability, disabled calendar or general workload do not identify scarcity; idle capacity is possible.','Need job/hour/skill capacity, demand, utilization and margin of displaced work.')
put('H13','unresolved','No sufficiently complete compatible-parts purchase and nonpurchase evidence was collected.',['market:M013','narratives:N016'],'Parts costs and maintenance vary, but that does not establish compatibility as a blocking mechanism.','Stock, price, lead time or low demand could dominate.','Need fitment task evidence, returns/errors, inventory and completed-order contribution.')
put('H14','unresolved','B&P presence and specialist discovery are observed; under-connection or lost jobs is unmeasured.',['journeys:UX08','competition:COMP-018','narratives:N075'],'Auto2000 has a B&P route and a specialist branch result; insurer/issuer attribution matters in repair narratives.','Existing insurer/referral routes may already perform well; viral cost claims have unresolved provenance.','Need incident-to-contact/authorization/repair outcomes and net contribution.')
put('H15','partly_corroborated','Household role and practical-fit differences are present in narratives; demand for a shareable artifact is unproven.',['narratives:N035','validation:V004','validation:V007','competition:COMP-010'],'Family preferences, a second household vehicle and spouse-related finance inputs indicate distinct roles.','One decision maker may still coordinate easily; mandatory finance documents are not evidence of coordination friction.','Need direct coordination burden, sharing behavior and task/choice consequences.')
put('H16','unresolved','Fleet administrator priorities relative to individual engagement were not established.',['reviews:REV-0003','market:M045'],'A consumer multi-car booking limit is reported; one subscription FAQ restricts personal use.','Neither proves fleet demand or inadequacy of existing specialist B2B channels.','Need fleet-specific process evidence, approvals, downtime and contract economics.')
put('H17','unresolved','Different tasks impose different data boundaries; causal trust/abandonment effects were not measured.',['journeys:UX03','journeys:UX05','journeys:UX06','journeys:UX07','journeys:UX11','competition:COMP-010'],'Finance and test-drive previews expose value before contact; workshop and appraisal previews stop at vehicle/plate requirements.','Those fields may be necessary for credible qualification; not every task gates value behind identity.','Need field purpose, eligibility effect, comprehension, consent and task outcome evidence.')
put('H18','unresolved','Representation anomalies were observed; distributed-governance causation and exact entity conflicts remain unresolved.',['journeys:UX01','journeys:UX02','competition:COMP-045'],'An implausible filter limit, TRUE airbag field and a navigation Rp0 value are bounded representation issues.','Price differences may reflect date/variant/offer scope; navigation placeholders are not confirmed free offers.','Need matched entity/version joins and publishing ownership/update process; no indexing or revenue effect inferred.')
put('H19','unresolved','Existing content and next-step routes are visible; disconnected relevant actions were not established broadly.',['journeys:UX02','journeys:UX03','competition:COMP-001','market:M018'],'Useful capabilities exist in several properties and tasks.','Informational pages may legitimately need no immediate commercial action; successful routes are countercases.','Need balanced query-to-answer-to-action tasks and actual assisted transitions.')
put('H20','unresolved','Relative commercial value of acquisition versus decision support cannot be ranked from this public sample.',['journeys:UX02','market:M003','market:M024'],'Decision uncertainty is plausible, while raw metadata alone cannot establish search losses.','High-intent discoverability may be the larger problem; no Search Console or conversion cohort was available.','Need comparable exposure, intent, search and transaction data; source ordering is not Google rank.')
put('H21','unresolved','Staff incentive or Single ID credit-allocation conflict was not directly observed.',['validation:V012','validation:V013','validation:V014'],'Staff-role accounts raise workload, documentation and price-authority questions.','Data quality, training or ordinary workflow could explain difficulty; no compensation policy or Single ID usage audit exists.','Need authorized policy and process evidence; role-play is not stakeholder testimony.')
put('H22','unresolved','Relative incremental value of rare lifecycle moments versus frequent engagement was not measured.',['market:M012','market:M016','market:M017','narratives:N018','validation:V001'],'Distinct job cadence and eligibility transitions are plausible commercially meaningful moments.','Useful frequent interaction may build independent value; low-mileage anecdotes do not settle app economics.','Need comparable all-channel cohorts and contribution outcomes, accounting for intent selection.')
put('H23','unresolved','The share of digital volume that is migration versus incremental remains unidentified.',['market:MC03','market:MC05','journeys:UX03'],'A zero-increment migration counterexample is mathematically valid; a useful digital task was observed.','Digital may win additional sales, capture or realizable efficiency; no all-channel counterfactual is available.','Need all-channel completed contribution and cost-to-serve comparison; app share alone is insufficient.')
put('H24','unresolved','Existing transaction-relevant battery evidence is supported; its highest-value stage was not identified.',['market:M021','market:M033','market:M034','competition:COMP-005','validation:V015'],'Condition information, protection and appraisal uncertainty plausibly interact.','Owners may value reassurance independently; scores may already be understood and priced in.','Need stage-specific certificate use, actual appraisal/choice outcomes and competing uncertainty measures.')
put('H25','unresolved','Different flow/stock and powertrain economics are supported; Auto2000 installed-base exposure remains unknown.',['market:MC01','market:MC02','market:M011','market:M012'],'Market-mix arithmetic can change aggregate share without segment underperformance; HEV/BEV needs differ.','Rapid BEV adoption could already change the relevant cohort; national new-sales data do not resolve dealer stock.','Need vehicle-in-use cohorts, age/mileage, retention and actual jobs/contribution.')
# Snapshot only input hashes and explicit observation references, not private source bodies.
files=[plan,root/'workstreams/market/evidence.json',root/'workstreams/market/economic_calculations.json',root/'workstreams/competition/evidence_matrix.json',root/'workstreams/reviews/reviews_derived.csv',root/'workstreams/reviews/FINDINGS.md',root/'workstreams/narratives/narrative_units.csv',root/'workstreams/narratives/validation_units.csv',root/'workstreams/narratives/validation_summary.json',root/'workstreams/datasets/market_analysis_summary.json',root/'workstreams/datasets/spklu_analysis_summary.json',root/'workstreams/site/page_observations.csv',root/'workstreams/site/summary.json',root/'workstreams/journeys/journey_observations.json',root/'workstreams/journeys/finance_scenarios.csv']
freeze=datetime.datetime.now(datetime.timezone.utc).isoformat();manifest=[]
for p in files:
 b=p.read_bytes();manifest.append({'path':str(p.relative_to(root)) if p.is_relative_to(root) else str(p),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()})
rows=[]
for r in original:
 x={'hypothesis_id':r['ID'],'initial_hypothesis':r['Working hypothesis'],'initial_rival':r['Strongest rival'],**A[r['ID']],'freeze_timestamp_utc':freeze,'assessor':'independent AI research agent; source-grounded review, not human validation'};rows.append(x)
assert len(rows)==25 and len({r['hypothesis_id'] for r in rows})==25
valid={'supported','contradicted','partly_corroborated','unresolved'};assert all(r['assessment_status'] in valid for r in rows)
(out/'hypothesis_assessment.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
with (out/'hypothesis_assessment.csv').open('w',newline='',encoding='utf8') as f:
 w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows({**r,'evidence_refs':'|'.join(r['evidence_refs'])} for r in rows)
(out/'hypothesis_input_manifest.json').write_text(json.dumps({'freeze_timestamp_utc':freeze,'inputs':manifest,'warning':'Files may evolve after freeze. Reassess material new evidence before final publication. Count changes do not automatically change mechanism conclusions.','source_provenance':'References use namespace and record ID. See hypothesis_reference_index.json.'},indent=2))
indices={
'market':{'path':'workstreams/market/evidence.json','id_field':'evidence_id'},
'market_calculations':{'path':'workstreams/market/economic_calculations.json','id_field':'calculation_id'},
'competition':{'path':'workstreams/competition/evidence_matrix.json','id_field':'record_id'},
'reviews':{'path':'workstreams/reviews/reviews_derived.csv','id_field':'evidence_id'},
'narratives':{'path':'workstreams/narratives/narrative_units.csv','id_field':'record_id'},
'validation':{'path':'workstreams/narratives/validation_units.csv','id_field':'record_id'},
'journeys':{'path':'workstreams/journeys/journey_observations.json','collection_key':'observations','id_field':'observation_id'}}
# MC references use market prefix for readable report but resolve to the calculation registry.
lookup={}
for ns,meta in indices.items():
 p=root/meta['path'];a=json.loads(p.read_text()) if p.suffix=='.json' else list(csv.DictReader(p.open(encoding='utf8')))
 if isinstance(a,dict):a=a[meta['collection_key']]
 for x in a:
  key=('market' if ns=='market_calculations' else ns)+':'+x[meta['id_field']];lookup[key]={'path':meta['path'],'id_field':meta['id_field'],'id':x[meta['id_field']]}
refs={s for r in rows for s in r['evidence_refs']};missing=sorted(refs-set(lookup));assert not missing,missing
(out/'hypothesis_reference_index.json').write_text(json.dumps({r:lookup[r] for r in sorted(refs)},indent=2))
counts={s:sum(r['assessment_status']==s for r in rows) for s in valid}
(out/'hypothesis_assessment_checks.json').write_text(json.dumps({'freeze_timestamp_utc':freeze,'hypotheses':25,'assessment_counts':counts,'business_mechanisms_unresolved':25,'unique_referenced_records':len(refs),'all_references_resolve':True,'causal_effects_established':0,'result':'passed'},indent=2))
print(json.dumps(counts),'refs',len(refs))
